+    for (uint32_t kIdx = self->ctx.curCoutStartIdx_; kIdx < self->ctx.tiling_->coutG; kIdx += self->ctx.kSegment_) {
+        self->ctx.curCoutStartIdx_ = kIdx;
+        UpdateSplitKTail<Intf>(self, kIdx);
