+string GetTime()
+{
+    time_t timep;
+    time(&timep);
+    char tmp[64];
+    strftime(tmp, sizeof(tmp), "%Y-%m-%d %H:%M:%S,000", localtime(&timep));
+    return tmp;
+}
+
+uint32_t GetDataTypeSize(DataType dt)
+{
+    uint32_t dilation = 1;
+    uint32_t oneByte = 1;
+    uint32_t twoByte = 2;
+    uint32_t fourByte = 4;
+    uint32_t eightByte = 8;
+
+    if (dt == ge::DT_FLOAT) {
+        dilation = fourByte;
+    } else if (dt == ge::DT_FLOAT16) {
+        dilation = twoByte;
+    } else if (dt == ge::DT_BF16) {
+        dilation = twoByte;
+    } else if (dt == ge::DT_INT16) {
+        dilation = twoByte;
+    } else if (dt == ge::DT_UINT16) {
+        dilation = twoByte;
+    } else if (dt == ge::DT_INT32) {
+        dilation = fourByte;
+    } else if (dt == ge::DT_UINT32) {
+        dilation = fourByte;
+    } else if (dt == ge::DT_INT64) {
+        dilation = eightByte;
+    } else if (dt == ge::DT_UINT64) {
+        dilation = eightByte;
+    } else if (dt == ge::DT_INT8) {
+        dilation = oneByte;
+    }
+    return dilation;
+}
+
+int32_t GenOnesData(
+    vector<int64_t> shapes, Tensor& input_tensor, TensorDesc& input_tensor_desc, DataType data_type, int value)
+{
+    input_tensor_desc.SetRealDimCnt(shapes.size());
+    size_t size = 1;
+    for (uint32_t i = 0; i < shapes.size(); i++) {
+        size *= shapes[i];
+    }
+    uint32_t data_len = size * GetDataTypeSize(data_type);
+    int32_t* pData = new (std::nothrow) int32_t[data_len];
+    for (uint32_t i = 0; i < size; ++i) {
+        *(pData + i) = value;
+    }
+    input_tensor = Tensor(input_tensor_desc, reinterpret_cast<uint8_t*>(pData), data_len);
+    return SUCCESS;
+}
+
+int32_t WriteDataToFile(string bin_file, uint64_t data_size, uint8_t* inputData)
+{
+    FILE* fp = fopen(bin_file.c_str(), "w");
+    fwrite(inputData, sizeof(uint8_t), data_size, fp);
+    fclose(fp);
+    return SUCCESS;
+}
+
+int CreateOppInGraph(
+    DataType inDtype, std::vector<ge::Tensor>& input, std::vector<Operator>& inputs, std::vector<Operator>& outputs,
+    Graph& graph)
+{
+    Status ret = SUCCESS;
+    auto add1 = op::MaxPoolGradWithArgmax("max_pool_grad_with_argmax");
+    vector<vector<int64_t>> shapes = {
+        {4, 1, 4, 4}, // x shape (input)
+        {4, 1, 2, 2}, // grad shape (gradient input)
+        {4, 1, 2, 2}  // argmax shape (indices from forward)
+    };
+    vector<vector<int64_t>> attrs = {
+        {1, 1, 2, 2}, // ksize
+        {1, 1, 2, 2}  // strides
+    };
+
+    ADD_INPUT(1, x, inDtype, shapes[0]);
+    ADD_INPUT(2, grad, inDtype, shapes[1]);
+    ADD_INPUT(3, argmax, DT_INT32, shapes[2]);
+    ADD_OUTPUT(4, y, inDtype, shapes[0]);
+    ADD_INPUT_ATTR(ksize, attrs[0]);
+    ADD_INPUT_ATTR(strides, attrs[1]);
+    ADD_INPUT_ATTR(padding, "VALID");
+    ADD_INPUT_ATTR(include_batch_in_index, false);
+    ADD_INPUT_ATTR(data_format, "NCHW");
+    outputs.push_back(add1);
+    return SUCCESS;
+}
