+int main(int argc, char* argv[])
+{
+    std::vector<ge::Tensor> input{};
+    std::vector<ge::Tensor> output{};
+    Graph graph("max_pool_grad_with_argmax_graph");
+
+    if (!InitEnv()) {
+        return FAILED;
